canonical.command_body:
#!/usr/bin/env bash
export ERL_FLAGS='+S 2:2'
export MIX_ENV=test
set -euo pipefail
{
  unbuffer mix format --check-formatted
  unbuffer mix compile --warnings-as-errors
  unbuffer mix test --warnings-as-errors --max-cases 1 apps/gaoxy_http/test apps/gaoxy_proxy/test apps/gaoxy/test apps/gaoxy_server/test
  /tmp/gaoxy-m3-h2-soak-venv/bin/python integration/h2_rfc/run.py --evidence docs/acceptance/evidence/m3/h2-rfc-s5-final
} 2>&1 | tee docs/acceptance/evidence/m3/canonical-s5-final.log
